package com.royalankit.zoya.service
import android.app.*;import android.content.*;import androidx.core.app.NotificationCompat;import com.royalankit.zoya.R
class AlarmReceiver:BroadcastReceiver(){override fun onReceive(c:Context,i:Intent){val ch="zoya_alerts";val nm=c.getSystemService(NotificationManager::class.java);if(android.os.Build.VERSION.SDK_INT>=26)nm.createNotificationChannel(NotificationChannel(ch,c.getString(R.string.alert_channel),NotificationManager.IMPORTANCE_HIGH));nm.notify((System.currentTimeMillis() and 0x7fffffff).toInt(),NotificationCompat.Builder(c,ch).setSmallIcon(R.drawable.ic_zoya).setContentTitle(c.getString(R.string.app_name)).setContentText(if(i.action?.endsWith("TIMER")==true)"Timer पूरा हो गया।" else "आपका alarm बज गया।").setAutoCancel(true).build())}}
